665: pub(crate) fn refresh_party_journey_forecast(
666:     ctx: &ReducerContext,
667:     party_id: &str,
668: ) -> Result<(), String> {
669:     let Some(mut journey) = ctx
670:         .db
671:         .party_journey_authority()
672:         .party_id()
673:         .find(party_id.to_string())
674:     else {
675:         return Ok(());
676:     };
677:     let party = ctx
678:         .db
679:         .party_authority()
680:         .id()
681:         .find(party_id.to_string())
682:         .ok_or("Party not found")?;
683:     let start = journey_local_minute(&journey, journey.completed_elapsed_minutes);
684:     // A persisted journey always describes its active leg. A return trip is a
685:     // new journey and must not be folded into a refreshed outbound forecast.
686:     let remaining = journey
687:         .total_movement_minutes
688:         .saturating_sub(journey.completed_movement_minutes);
689:     let itinerary = forecast_itinerary(
690:         start,
691:         remaining,
692:         party.walking_minutes_per_day,
693:         party.travel_at_night,
694:         &party_itinerary_members(ctx, party_id)?,
695:     )
696:     .ok_or("Unable to forecast the remaining itinerary")?;
697:     if itinerary.truncated {
698:         return Err("Journey requires too many itinerary checkpoints".into());
699:     }
700:     journey.walking_minutes_per_day = party.walking_minutes_per_day;
701:     journey.travel_at_night = party.travel_at_night;
702:     journey.total_elapsed_minutes = journey
703:         .completed_elapsed_minutes
704:         .saturating_add(itinerary.total_elapsed_minutes);
705:     let forecast_camp_intervals = itinerary_camps(&itinerary)
706:         .into_iter()
707:         .map(|mut interval| {
708:             interval.movement_minute = interval
709:                 .movement_minute
710:                 .saturating_add(journey.completed_movement_minutes);
711:             interval.elapsed_start_minute = interval
712:                 .elapsed_start_minute
713:                 .saturating_add(journey.completed_elapsed_minutes);
714:             interval
715:         })
716:         .collect();
717:     journey.forecast_camp_intervals = forecast_camp_intervals;
718:     ctx.db.party_journey_authority().party_id().update(journey);
719:     Ok(())
720: }
